import { useEffect, useRef, useState } from "react";
export const MIN_SECONDS_TO_SHOW = 7;
export const useProgress = ({ isOpen, onClose, showSeconds = MIN_SECONDS_TO_SHOW }) => {
    const [progress, setProgress] = useState(100);
    const isFinishedRef = useRef(false);
    const seconds = showSeconds <= 0 ? MIN_SECONDS_TO_SHOW : showSeconds;
    useEffect(() => {
        if (isOpen && !isFinishedRef.current) {
            const interval = setInterval(() => {
                setProgress((prev) => {
                    if (isFinishedRef.current) {
                        return prev;
                    }
                    if (prev < 0) {
                        clearInterval(interval);
                        isFinishedRef.current = true;
                        setTimeout(onClose);
                        return 0;
                    }
                    return prev - 1;
                });
            }, seconds * 10);
            return () => clearInterval(interval);
        }
        return undefined;
    }, [isOpen, onClose, seconds, showSeconds]);
    return { progress };
};
